.mode-badge.combat { background: var(--combat-primary); color: #1a1520; }
.mode-badge.nsfw { background: var(--nsfw-primary); color: #1a1520; }

.mode-card { background: rgba(26, 21, 32, 0.5); border: 1px solid var(--border-color); border-radius: var(--radius-m); padding: 14px; margin-bottom: 10px; }
.mode-card-title { font-size: 13px; font-weight: 700; color: var(--sakura); margin-bottom: 8px; display: flex; align-items: center; gap: 4px; }
.mode-card-content { font-size: 12px; color: var(--tn-fg-dim); line-height: 1.6; }
.mode-card-content em, .mode-card-content i { color: var(--sakura-bright); font-style: normal; }

/* 战斗模式专属样式 */
.combat-table { width: 100%; border-collapse: collapse; margin: 8px 0; font-size: 11px; }
.combat-table th, .combat-table td { padding: 6px 8px; border: 1px solid var(--border-color); text-align: left; }
.combat-table th { background: rgba(248, 113, 113, 0.15); color: var(--combat-secondary); font-weight: 700; }
.combat-table td { color: var(--tn-fg-dim); }
.combat-stat-bar { display: flex; align-items: center; gap: 6px; }
.combat-stat-fill { height: 8px; border-radius: 4px; transition: width 0.3s; }
.combat-stat-fill.hp { background: linear-gradient(90deg, #ef4444, #f87171); }
.combat-stat-fill.mp { background: linear-gradient(90deg, #3b82f6, #60a5fa); }
.combat-stat-fill.sp { background: linear-gradient(90deg, #22c55e, #4ade80); }

/* NSFW模式专属样式 */
.nsfw-warning { background: rgba(244, 114, 182, 0.1); border: 2px dashed var(--nsfw-border); border-radius: var(--radius-m); padding: 10px; margin-bottom: 12px; }
.nsfw-warning-title { font-size: 11px; font-weight: 800; color: var(--nsfw-primary); margin-bottom: 4px; }
.nsfw-warning-content { font-size: 10px; color: var(--nsfw-secondary); }
.nsfw-psychology-card { background: rgba(244, 114, 182, 0.08); border: 1px solid var(--nsfw-border); border-radius: var(--radius-m); padding: 12px; margin-bottom: 8px; }
.nsfw-psychology-type { font-size: 12px; font-weight: 700; color: var(--nsfw-secondary); margin-bottom: 6px; }
.nsfw-psychology-desc { font-size: 11px; color: var(--tn-fg-dim); }

/* ========== Character Analysis Styles ========== */
.char-section { margin-bottom: 14px; }
.char-nav { display: flex; gap: 4px; margin-bottom: 12px; overflow-x: auto; padding-bottom: 4px; flex-wrap: wrap; }
.char-btn { padding: 6px 12px; font-size: 12px; font-weight: 600; color: var(--tn-comment); background: rgba(26, 21, 32, 0.5); border: 2px solid var(--border-color); border-radius: var(--radius-s); cursor: pointer; white-space: nowrap; transition: all 0.2s; }
.char-btn:hover { color: var(--sakura); border-color: var(--sakura-dim); box-shadow: 0 0 10px var(--sakura-glow); }
.char-btn.active { background: linear-gradient(135deg, var(--sakura), var(--gold)); color: #1a1520; font-weight: 800; border-color: var(--gold-bright); box-shadow: 0 0 15px var(--sakura-glow); }
.char-detail { display: none; }
.char-detail.active { display: block; }
.char-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; padding-bottom: 8px; border-bottom: 2px dashed var(--border-bright); }
.char-name { font-size: 16px; font-weight: 800; color: var(--sakura-bright); text-shadow: 0 0 12px var(--sakura-glow); }
.char-badge { font-size: 9px; color: #1a1520; background: linear-gradient(135deg, var(--sakura), var(--gold)); padding: 3px 8px; border-radius: 6px; font-weight: 700; box-shadow: 0 0 10px var(--sakura-glow); }
.char-info-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; margin-bottom: 12px; }
.char-info-item { background: rgba(26, 21, 32, 0.5); border: 1px solid var(--border-color); border-radius: var(--radius-s); padding: 8px 10px; }
.char-info-label { font-size: 10px; color: var(--tn-comment); margin-bottom: 2px; }
.char-info-value { font-size: 12px; color: var(--tn-fg); font-weight: 600; }
.char-psychology { background: rgba(255, 183, 197, 0.08); border: 1px solid rgba(255, 183, 197, 0.25); border-radius: var(--radius-m); padding: 12px; margin-bottom: 10px; }
.char-psychology-title { font-size: 11px; font-weight: 700; color: var(--sakura); margin-bottom: 6px; }
.char-psychology-content { font-size: 12px; color: var(--tn-fg-dim); line-height: 1.6; }
.char-action { background: rgba(201, 160, 220, 0.1); border: 1px solid rgba(201, 160, 220, 0.25); border-radius: var(--radius-m); padding: 10px; }
.char-action-title { font-size: 11px; font-weight: 700; color: var(--accent-purple); margin-bottom: 4px; }
.char-action-content { font-size: 12px; color: var(--tn-fg-dim); }

/* ========== Memory Styles ========== */
#mem-nav { display: grid; grid-template-columns: repeat(5, 1fr); gap: 4px; margin-bottom: 12px; }
.mem-nav-btn { background: rgba(26, 21, 32, 0.5); border: 2px solid var(--border-color); border-radius: var(--radius-s); padding: 8px 4px; font-size: 10px; font-weight: 600; font-family: var(--font-mono); color: var(--tn-comment); text-align: center; cursor: pointer; transition: all 0.2s; }
.mem-nav-btn:hover { color: var(--sakura); border-color: var(--sakura-dim); }
.mem-nav-btn.active { background: linear-gradient(135deg, var(--sakura), var(--gold)); color: #1a1520; font-weight: 800; border-color: var(--gold-bright); box-shadow: 0 0 12px var(--sakura-glow); }
.mem-content { min-height: 100px; }
.mem-comment { background: rgba(255, 183, 197, 0.1); color: var(--sakura); padding: 8px 12px; border-radius: var(--radius-s); font-size: 12px; margin-bottom: 12px; border: 2px dashed rgba(255, 183, 197, 0.35); }
.mem-cell-tags { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 12px; }
.mem-cell-tag { background: rgba(255, 183, 197, 0.12); color: var(--sakura); padding: 4px 8px; border-radius: 4px; font-size: 11px; border: 1px solid rgba(255, 183, 197, 0.25); }
.mem-long-block { font-size: 13px; color: var(--tn-fg-dim); background: rgba(26, 21, 32, 0.5); padding: 12px; border-radius: var(--radius-m); line-height: 1.6; margin-bottom: 12px; border-left: 3px solid var(--sakura); }

/* ========== Reason Styles ========== */
.reason-section { margin-bottom: 14px; }
.reason-title { font-size: 14px; font-weight: 800; color: var(--accent-purple); margin-bottom: 10px; text-shadow: 0 0 10px var(--purple-glow); }
.reason-list { font-size: 12px; color: var(--tn-fg-dim); }
.reason-item { padding: 6px 0; border-bottom: 1px dashed rgba(201, 160, 220, 0.2); display: flex; gap: 8px; }
.reason-item:last-child { border-bottom: none; }
.reason-code { color: var(--accent-blue); font-weight: 600; font-family: var(--font-mono); min-width: 50px; }
.reason-desc { flex: 1; }

/* ========== Supplement Styles ========== */
.supplement-section { margin-bottom: 14px; }
.supplement-title { font-size: 14px; font-weight: 800; color: var(--gold-bright); margin-bottom: 10px; text-shadow: 0 0 10px var(--gold-glow); }
.supplement-item { background: rgba(26, 21, 32, 0.5); border: 1px solid var(--border-color); border-radius: var(--radius-m); padding: 10px 12px; margin-bottom: 8px; border-left: 3px solid var(--gold); }
.supplement-type { font-size: 10px; color: var(--gold); font-weight: 700; margin-bottom: 4px; }
.supplement-content { font-size: 12px; color: var(--tn-fg-dim); line-height: 1.5; }

/* ========== Common Styles ========== */
.empty-state { text-align: center; color: var(--tn-comment); padding: 40px 20px; font-size: 13px; }
.empty-state::before { content: '🌸'; margin-right: 6px; }
.empty-state::after { content: '🌸'; margin-left: 6px; }
.loading-tip { text-align: center; color: var(--tn-comment); padding: 30px; font-size: 12px; }
.loading-tip::before { content: '🌸'; margin-right: 6px; }
.loading-tip::after { content: '🌸'; margin-left: 6px; }
</style>
</head>
<body>

<div class="story-panel expanded" id="storyPanel">
<div class="panel-top">
    <div class="collapse-btn" id="collapseBtn" onclick="togglePanel()" title="折叠/展开">▼</div>
    <div class="main-avatar show-default" id="mainAvatar"><span class="default-sakura-icon">🎭</span></div>
    <div class="panel-title">埃瑟尔德大陆</div>
    <div class="version-badge">V1.0 美化版</div>
</div>

<div class="panel-header">
    <div class="tab-bar" id="mainTabBar">
        <div class="tab-bar-btn active" data-tab="userinput" onclick="switchMainTab('userinput', this)">
            <div class="icon-shape icon-scroll"><div class="scroll-glow"></div><div class="scroll-body"></div><div class="scroll-top"></div><div class="scroll-bottom"></div></div>
            <span class="tab-tooltip">用户输入</span>
        </div>
        <div class="tab-bar-btn" data-tab="legitimacy" onclick="switchMainTab('legitimacy', this)">
            <div class="icon-shape icon-scale"><div class="scale-top"></div><div class="scale-beam"></div><div class="scale-pole"></div><div class="scale-left"></div><div class="scale-right"></div></div>
            <span class="tab-tooltip">合理性审查</span>
        </div>
        <div class="tab-bar-btn" data-tab="mode" onclick="switchMainTab('mode', this)">
            <div class="icon-shape icon-mode icon-sun"><div class="sun-core"></div><div class="sun-rays"></div></div>
            <span class="tab-tooltip">模式分析</span>
        </div>
        <div class="tab-bar-btn" data-tab="character" onclick="switchMainTab('character', this)">
            <div class="icon-shape icon-person"><div class="person-head"></div><div class="person-body"></div><div class="person-legs"></div></div>
            <span class="tab-tooltip">人物状态</span>
        </div>
        <div class="tab-bar-btn" data-tab="memory" onclick="switchMainTab('memory', this)">
            <div class="icon-shape icon-crystal"><div class="crystal-body"><div class="crystal-top"></div><div class="crystal-bottom"></div></div><div class="crystal-glow-base"></div></div>
            <span class="tab-tooltip">记忆召回</span>
        </div>
        <div class="tab-bar-btn" data-tab="supplement" onclick="switchMainTab('supplement', this)">
            <div class="icon-shape icon-star"></div>
            <span class="tab-tooltip">补充信息</span>
        </div>
    </div>
</div>

<div class="panel-content">
<div class="tab-content-area">
    <div class="tab-pane active" id="pane-userinput"><div id="userInputContent"></div></div>
    <div class="tab-pane" id="pane-legitimacy"><div id="legitimacyContent"></div></div>
    <div class="tab-pane" id="pane-mode">
        <div id="modeHeader"></div>
        <div id="modeContent"></div>
    </div>
    <div class="tab-pane" id="pane-character">
        <div class="char-nav" id="charNav"></div>
        <div id="charDetails"></div>
    </div>
    <div class="tab-pane" id="pane-memory">
        <div id="mem-nav"></div>
        <div class="mem-content" id="mem-content"></div>
    </div>
    <div class="tab-pane" id="pane-supplement">
        <div id="supplementContent"></div>
    </div>
</div>
</div>
</div>

<script>
(function(){
    var tooltipTimeout = null;

    function escapeHtml(t){ if(!t) return ''; var d = document.createElement('div'); d.textContent = t; return d.innerHTML; }

    function updateHeight(){ setTimeout(function(){ var h = document.body.scrollHeight; if(window.parent && window.parent !== window) window.parent.postMessage({type:'resizeIframe', height:h}, '*'); }, 50); }
    window.updateHeight = updateHeight;

    window.switchMainTab = function(tabId, btn) {
        var panel = document.getElementById('storyPanel');
        if(!panel.classList.contains('expanded')) panel.classList.add('expanded');
        document.querySelectorAll('.tab-bar-btn').forEach(function(b) { b.classList.toggle('active', b.getAttribute('data-tab') === tabId); });
        document.querySelectorAll('.tab-pane').forEach(function(pane) { pane.classList.toggle('active', pane.id === 'pane-' + tabId); });
        if (btn) showTooltip(btn);
        updateHeight();
    };

    window.togglePanel = function() { document.getElementById('storyPanel').classList.toggle('expanded'); updateHeight(); };

    function showTooltip(btn) {
        var tip = btn.querySelector('.tab-tooltip'); if (!tip) return;
        clearAllTooltips(); if (tooltipTimeout) clearTimeout(tooltipTimeout);
        tip.style.opacity = ''; tip.classList.remove('hide'); tip.classList.add('show');
        tooltipTimeout = setTimeout(function() { tip.classList.remove('show'); tip.classList.add('hide'); setTimeout(function() { tip.classList.remove('hide'); tip.style.opacity = '0'; }, 250); }, 1500);
    }

    function clearAllTooltips() { document.querySelectorAll('.tab-tooltip').forEach(function(t) { t.classList.remove('show','hide'); t.style.opacity = '0'; }); }

    /* ========== Extract Tags from Chat ========== */
    function extractTagFromChat(tagName){
        try{
            var chat = null;
            if(typeof getContext === 'function'){ try{ var ctx = getContext(); chat = ctx && ctx.chat ? ctx.chat : null; }catch(e){} }
            if(!chat && typeof window.SillyTavern !== 'undefined') chat = window.SillyTavern.chat ? window.SillyTavern.chat : null;
            if(!chat) return '';
            var regex = new RegExp('<'+tagName+'>([\\s\\S]*?)<\\/'+tagName+'>', 'i');
            for(var i = chat.length - 1; i >= 0; i--){
                var msg = chat[i]; if(!msg) continue;
                var sources = [msg.extra && msg.extra.qrf_plot ? msg.extra.qrf_plot : null, msg.mes, msg.qrf_plot];
                if(msg.swipes && Array.isArray(msg.swipes)){ for(var s = 0; s < msg.swipes.length; s++){ var swipe = msg.swipes[s]; if(typeof swipe === 'string') sources.push(swipe); else if(swipe && swipe.extra && swipe.extra.qrf_plot) sources.push(swipe.extra.qrf_plot); } }
                for(var j = 0; j < sources.length; j++){ if(!sources[j]) continue; var match = sources[j].match(regex); if(match && match[1]) return match[1].trim(); }
            }
        }catch(e){}
        return '';
    }

    function extractUserInputFromChat(){ return extractTagFromChat('User_Input'); }
    function extractLegitimacyFromChat(){ return extractTagFromChat('legitimacy_check'); }
    function extractModeFromChat(){ return extractTagFromChat('mode_analysis'); }
    function extractCharacterFromChat(){ return extractTagFromChat('character_analysis'); }
    function extractRecallFromChat(){ return extractTagFromChat('recall'); }
    function extractReasonFromChat(){ return extractTagFromChat('reason'); }
    function extractSupplementFromChat(){ return extractTagFromChat('supplement'); }

    /* ========== User Input Parser ========== */
    function parseUserInput(raw) {
        return { content: raw.trim() };
    }

    function initUserInput() {
        var container = document.getElementById('userInputContent');
        var raw = extractUserInputFromChat();
        if(!raw.trim()) { container.innerHTML = '<div class="empty-state">等待用户输入...</div>'; return; }
        var html = '<div class="user-input-section">';
        html += '<div class="user-input-title">📜 用户输入</div>';
        html += '<div class="user-input-content">' + escapeHtml(raw) + '</div>';
        html += '</div>';
        container.innerHTML = html;
    }

    /* ========== Legitimacy Check Parser ========== */
    function parseLegitimacy(raw) {
        var r = { result: '', items: [], summary: '' };
        if(!raw.trim()) return r;
        var resultM = raw.match(/##\s*审查结果[：:]\s*(✅\s*通过|❌\s*不通过|通过|不通过)/i);
        if(resultM) r.result = resultM[1].trim();
        var itemPattern = /###\s*\d+\.\s*([^\n]+)\n[-*]\s*状态[：:]\s*(✅\s*通过|❌\s*不通过)[^\n]*\n[-*]\s*说明[：:]\s*([^\n]+)/gi;
        var m;
        while((m = itemPattern.exec(raw)) !== null) {
            r.items.push({ title: m[1].trim(), status: m[2].trim(), desc: m[3].trim() });
        }
        var summaryM = raw.match(/##\s*综合评价\s*\n([\s\S]*?)(?=<\/legitimacy_check>|$)/i);
        if(summaryM) r.summary = summaryM[1].trim();
        return r;
    }

    function initLegitimacy() {
        var container = document.getElementById('legitimacyContent');
        var parsed = parseLegitimacy(extractLegitimacyFromChat());
        if(!parsed.result && parsed.items.length === 0) { container.innerHTML = '<div class="empty-state">暂无合理性审查</div>'; return; }
        var html = '<div class="legitimacy-section">';
        html += '<div class="legitimacy-header">';
        html += '<span class="legitimacy-title">⚖️ 合理性审查报告</span>';
        if(parsed.result) {
            var isPass = parsed.result.indexOf('通过') !== -1 && parsed.result.indexOf('不通过') === -1;
            html += '<span class="legitimacy-result ' + (isPass ? 'pass' : 'fail') + '">' + escapeHtml(parsed.result) + '</span>';
        }
        html += '</div>';
        if(parsed.items.length) {
            html += '<div class="legitimacy-card">';
            parsed.items.forEach(function(item) {
                var isPass = item.status.indexOf('通过') !== -1 && item.status.indexOf('不通过') === -1;
                html += '<div class="legitimacy-item">';
                html += '<span class="legitimacy-item-icon">' + (isPass ? '✅' : '❌') + '</span>';
                html += '<div class="legitimacy-item-content">';
                html += '<div class="legitimacy-item-title">' + escapeHtml(item.title) + '</div>';
                html += '<div class="legitimacy-item-desc">' + escapeHtml(item.desc) + '</div>';
                html += '</div></div>';
            });
            html += '</div>';
        }
        if(parsed.summary) {
            html += '<div class="legitimacy-summary">📝 ' + escapeHtml(parsed.summary) + '</div>';
        }
        html += '</div>';
        container.innerHTML = html;
    }

    /* ========== Mode Analysis Parser ========== */
    function detectMode(raw) {
        if(raw.indexOf('战斗场景分析') !== -1 || raw.indexOf('战斗模式') !== -1) return 'combat';
        if(raw.indexOf('NSFW场景分析') !== -1 || raw.indexOf('NSFW模式') !== -1) return 'nsfw';
        return 'daily';
    }

    function parseModeAnalysis(raw) {
        var r = { mode: detectMode(raw), sections: [] };
        if(!raw.trim()) return r;
        var sectionPattern = /##\s*([^\n]+)\n([\s\S]*?)(?=##\s|$)/gi;
        var m;
        while((m = sectionPattern.exec(raw)) !== null) {
            var title = m[1].trim();
            var content = m[2].trim();
            if(title && content) {
                r.sections.push({ title: title, content: content });
            }
        }
        if(r.sections.length === 0) {
            r.sections.push({ title: '场景分析', content: raw.trim() });
        }
        return r;
    }

    function initMode() {
        var headerContainer = document.getElementById('modeHeader');
        var contentContainer = document.getElementById('modeContent');
        var raw = extractModeFromChat();
        if(!raw.trim()) { headerContainer.innerHTML = ''; contentContainer.innerHTML = '<div class="empty-state">暂无模式分析</div>'; return; }
        var parsed = parseModeAnalysis(raw);
        var modeClass = parsed.mode;
        var modeName = parsed.mode === 'combat' ? '⚔️ 战斗模式' : (parsed.mode === 'nsfw' ? '💕 NSFW模式' : '☀️ 日常模式');
        var headerHtml = '<div class="mode-header ' + modeClass + '">';
        headerHtml += '<span class="mode-title">' + modeName + '</span>';
        headerHtml += '<span class="mode-badge ' + modeClass + '">' + (parsed.mode === 'combat' ? '战斗中' : (parsed.mode === 'nsfw' ? '私密' : '日常')) + '</span>';
        headerHtml += '</div>';
        headerContainer.innerHTML = headerHtml;
        var contentHtml = '<div class="mode-section">';
        parsed.sections.forEach(function(section) {
            contentHtml += '<div class="mode-card">';
            contentHtml += '<div class="mode-card-title">📋 ' + escapeHtml(section.title) + '</div>';
            contentHtml += '<div class="mode-card-content">' + escapeHtml(section.content).replace(/\n/g, '<br>') + '</div>';
            contentHtml += '</div>';
        });
        contentHtml += '</div>';
        contentContainer.innerHTML = contentHtml;
    }

    /* ========== Character Analysis Parser ========== */
    function parseCharacterAnalysis(raw) {
        var r = { chars: [], note: '' };
        if(!raw.trim()) return r;
        var charPattern = /###\s*📊\s*([^\n]+)\n([\s\S]*?)(?=###\s*📊|---+|✅\s*分析完成|$)/gi;
        var m;
        while((m = charPattern.exec(raw)) !== null) {
            var name = m[1].trim();
            var content = m[2].trim();
            if(name && content) {
                var charData = { name: name, raw: content };
                var infoPatterns = [
                    { key: '基础信息', pattern: /\*\*基础信息\*\*[：:]?\s*([^\n]+)/i },
                    { key: '当前状态', pattern: /\*\*当前状态\*\*[：:]?\s*([^\n]+)/i },
                    { key: '心理状态', pattern: /\*\*心理状态\*\*[：:]?\s*([^\n]+)/i },
                    { key: '认知边界', pattern: /\*\*认知边界\*\*[：:]?\s*([^\n]+)/i },
                    { key: '行为预测', pattern: /\*\*行为预测\*\*[：:]?\s*([^\n]+)/i },
                    { key: '情绪优化', pattern: /\*\*情绪优化\*\*[：:]?\s*([^\n]+)/i },
                    { key: '主动性建议', pattern: /\*\*主动性建议\*\*[：:]?\s*([^\n]+)/i }
                ];
                charData.info = {};
                infoPatterns.forEach(function(p) {
                    var match = content.match(p.pattern);
                    if(match) charData.info[p.key] = match[1].trim();
                });
                r.chars.push(charData);
            }
        }
        var noteM = raw.match(/\*\*核心原则\*\*[：:]?\s*([^\n]+)/i);
        if(noteM) r.note = noteM[1].trim();
        return r;
    }

    window.switchChar = function(idx) {
        document.querySelectorAll('#charNav .char-btn').forEach(function(btn, i) { btn.classList.toggle('active', i === idx); });
        document.querySelectorAll('#charDetails .char-detail').forEach(function(d, i) { d.classList.toggle('active', i === idx); });
        updateHeight();
    };

    function initCharacter() {
        var navContainer = document.getElementById('charNav');
        var detailsContainer = document.getElementById('charDetails');
        var raw = extractCharacterFromChat();
        if(!raw.trim()) { navContainer.innerHTML = ''; detailsContainer.innerHTML = '<div class="empty-state">暂无人物分析</div>'; return; }
        var parsed = parseCharacterAnalysis(raw);
        if(parsed.chars.length === 0) { navContainer.innerHTML = ''; detailsContainer.innerHTML = '<div class="empty-state">暂无人物分析</div>'; return; }
        var navHtml = '', detailsHtml = '';
        parsed.chars.forEach(function(char, idx) {
            var isActive = idx === 0 ? 'active' : '';
            var cleanName = char.name.split(/[\(（]/)[0].trim();
            navHtml += '<div class="char-btn ' + isActive + '" onclick="switchChar(' + idx + ')">' + escapeHtml(cleanName) + '</div>';
            detailsHtml += '<div class="char-detail ' + isActive + '">';
            detailsHtml += '<div class="char-header"><span class="char-name">' + escapeHtml(cleanName) + '</span><span class="char-badge">📊 人物状态</span></div>';
